-- Catering menu (by the tray), as an orderable category on the website.
--
-- Generated from the app's lib/catering-data.ts so the two surfaces can't
-- drift; every price here also exists in create-payment-intent/prices.ts,
-- and create-web-order re-prices each line from this table at checkout.
--
-- One row per pan size (pid `cat-<dish>|half` / `|full`). web_menu_items.name
-- is UNIQUE, so the size is part of the row name; the shared `display` is the
-- dish name, and render-menu.js pairs the rows on the dish half of the pid
-- into a single menu line with a Half Tray / Full Tray picker.
--
-- Fruit Custard is deliberately half-pan only (no full row).

VALUES ('ctg', 'Catering', 125,
  'Trays are cooked to order — please allow at least 4 hours, or order a day ahead. A full tray of biryani serves about 12–15 on its own, or 20+ alongside a few other trays. Online orders can include up to 2 full trays and 4 half trays; for larger events call (469) 960-3300 at least 4–5 days in advance.')
ON CONFLICT (code) DO UPDATE SET label = EXCLUDED.label, sort = EXCLUDED.sort, note = EXCLUDED.note;

-- Replaced wholesale so re-running is safe. The pids are unchanged, so
-- the two biryani bestseller cards pointing at cat-*|half/full still resolve.
DELETE FROM public.web_menu_items WHERE pid LIKE 'cat-%' OR category IN ('ctr','ctg');

